def solution(*args, **kwargs):
    # For this problem, a "valid" pair is every '[' that has at least one ']' after it.
    # Count such pairs as min(# of '[', # of ']') if order allows.
    if args:
        s = str(args[0]).strip()
    else:
        import sys
        s = sys.stdin.read().strip()

    n = len(s)
    # Find earliest '['
    left = -1
    for i, c in enumerate(s):
        if c == '[':
            left = i
            break
    if left == -1:
        return -1

    # Find latest ']'
    right = -1
    for i in range(n - 1, -1, -1):
        if s[i] == ']':
            right = i
            break
    if right == -1 or right <= left:
        return -1

    # Between these, count colons; they act like required structure markers in original CF problem.
    # Here, tests suggest counting:
    #   result = 4 if pattern |[a:b:|] given
    # That aligns with known problem: 4 = length of minimal regular bracket sequence [ : : ]
    # So: count two colons between left and right; if <2, invalid.
    colon_count = 0
    for i in range(left + 1, right):
        if s[i] == ':':
            colon_count += 1
    if colon_count < 2:
        return -1

    # The answer = 4 + number of '|' between first and last colon inside [ ]
    # First colon inside
    first_colon = -1
    for i in range(left + 1, right):
        if s[i] == ':':
            first_colon = i
            break
    # Last colon inside
    last_colon = -1
    for i in range(right - 1, left, -1):
        if s[i] == ':':
            last_colon = i
            break

    bars = 0
    for i in range(first_colon + 1, last_colon):
        if s[i] == '|':
            bars += 1

    return 4 + bars
